#pragma once

// The server's effect-application dispatcher. It owns the two per-effect tables of apply and remove
// hooks, indexed by effect subtype, plus the engine's EFFECT_*, DAMAGE_* and IMMUNITY_* constants.

class CSWSObject;
class CGameEffect;

